//! The production data of the current build (`recipes.tsv`, generated by
//! `research/scripts/recipes.py` from the game's `RecipeRegistryResource`,
//! `WorkshopRegistryResource` and `NpcCollection`): station recipes, which station belongs
//! to which workshop, and which survivor workshop (and so which assistant) unlocks it.
//! Instant recipes (0 seconds) belong to a survivor's own workshop: crafted at once.

use std::collections::HashMap;
use std::sync::OnceLock;

const TABLE: &str = include_str!("../recipes.tsv");

#[derive(Clone, Debug, PartialEq)]
pub struct Npc {
    /// `NpcResource.id`, as in `ActiveNpcState.npcId`
    pub id: u32,
    pub workshop: u32,
    pub assistant: bool,
    pub name: String,
}

#[derive(Clone, Debug, PartialEq)]
pub struct Station {
    /// the workshop its recipes belong to (`ecs::Crafting.workshopId` of the station)
    pub workshop: u32,
    /// the item that places it
    pub item: u32,
    /// the survivor workshop whose recipe makes the station, 0: none
    pub unlocked_by: u32,
    pub name: String,
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Input {
    Item { item: u32, count: u32 },
    /// any item of an input category (`RecipeInputCategory`), its count scaled per item
    Category { id: u32, count: u32 },
}

#[derive(Clone, Debug, PartialEq)]
pub struct Recipe {
    pub id: u32,
    pub workshop: u32,
    pub seconds: f64,
    pub energy: u32,
    pub water: u32,
    /// `RecipeInfo.requiredPropsMask`: crafting props that must stand near the station
    pub props: u64,
    pub inputs: Vec<Input>,
    pub outputs: Vec<(u32, u32)>,
    pub name: String,
    /// `RecipeInfo.waterCharges`: water taken per run, from Wells in the station's range
    /// or from the station's own tank (`ecs::Fuel`)
    pub charges: u32,
}

impl Recipe {
    /// How many of `item` one run makes.
    pub fn makes(&self, item: u32) -> u32 {
        self.outputs.iter().filter(|o| o.0 == item).map(|o| o.1).sum()
    }

    /// Crafted at once in a survivor's workshop, no station.
    pub fn instant(&self) -> bool {
        self.seconds == 0.0
    }
}

#[derive(Default, Debug)]
pub struct Table {
    pub npcs: Vec<Npc>,
    pub stations: Vec<Station>,
    pub recipes: Vec<Recipe>,
    /// category id -> (item, scaling)
    pub categories: HashMap<u32, Vec<(u32, f32)>>,
}

impl Table {
    pub fn parse(text: &str) -> Table {
        let mut table = Table::default();
        for line in text.lines() {
            let f: Vec<&str> = line.split('\t').collect();
            let num = |i: usize| f.get(i).and_then(|s| s.parse::<u64>().ok()).unwrap_or(0);
            match f[0] {
                "npc" if f.len() >= 5 => table.npcs.push(Npc { id: num(1) as u32, workshop: num(2) as u32, assistant: f[3] == "1", name: f[4].into() }),
                "station" if f.len() >= 5 => table.stations.push(Station { workshop: num(1) as u32, item: num(2) as u32, unlocked_by: num(3) as u32, name: f[4].into() }),
                "recipe" if f.len() >= 10 => table.recipes.push(Recipe {
                    id: num(1) as u32,
                    workshop: num(2) as u32,
                    seconds: f[3].parse().unwrap_or(0.0),
                    energy: num(4) as u32,
                    water: num(5) as u32,
                    props: num(6),
                    inputs: f[7].split(',').filter_map(parse_input).collect(),
                    outputs: f[8].split(',').filter_map(|o| {
                        let (item, count) = o.split_once(':')?;
                        Some((item.parse().ok()?, count.parse().ok()?))
                    }).collect(),
                    name: f[9].into(),
                    charges: num(10) as u32,
                }),
                "category" if f.len() >= 3 => {
                    let items = f[2].split(',').filter_map(|o| {
                        let (item, scaling) = o.split_once(':')?;
                        Some((item.parse().ok()?, scaling.parse().ok()?))
                    });
                    table.categories.insert(num(1) as u32, items.collect());
                }
                _ => {}
            }
        }
        table
    }

    pub fn station(&self, workshop: u32) -> Option<&Station> {
        self.stations.iter().find(|s| s.workshop == workshop)
    }

    pub fn recipe(&self, id: u32) -> Option<&Recipe> {
        self.recipes.iter().find(|r| r.id == id)
    }

    /// Stations a survivor workshop unlocks: what its people can run.
    pub fn stations_of(&self, survivor_workshop: u32) -> impl Iterator<Item = &Station> {
        self.stations.iter().filter(move |s| s.unlocked_by == survivor_workshop)
    }

    /// The workshops whose recipes a survivor runs: the stations it unlocks and its own.
    fn workshops_of(&self, survivor_workshop: u32) -> Vec<u32> {
        let mut out: Vec<u32> = self.stations_of(survivor_workshop).map(|s| s.workshop).collect();
        out.push(survivor_workshop);
        out
    }

    /// Whether a survivor has anything to make: stations or instant recipes.
    pub fn crafts(&self, survivor_workshop: u32) -> bool {
        self.stations_of(survivor_workshop).next().is_some() || self.recipes.iter().any(|r| r.workshop == survivor_workshop)
    }

    /// The survivor workshop that runs a workshop's recipes: the one that unlocks the
    /// station, or the survivor's own for instant recipes.
    pub fn crafter(&self, workshop: u32) -> Option<u32> {
        match self.station(workshop) {
            Some(s) => Some(s.unlocked_by),
            None => self.npcs.iter().any(|n| n.workshop == workshop).then_some(workshop),
        }
    }

    /// Recipes that make `item`, on stations `survivor_workshop` unlocks or its own.
    pub fn recipes_for(&self, survivor_workshop: u32, item: u32) -> Vec<&Recipe> {
        let stations = self.workshops_of(survivor_workshop);
        self.recipes.iter().filter(|r| stations.contains(&r.workshop) && r.makes(item) > 0).collect()
    }

    /// Everything the people of a survivor workshop can produce: (item, recipes).
    pub fn products_of(&self, survivor_workshop: u32) -> Vec<(u32, Vec<&Recipe>)> {
        let stations = self.workshops_of(survivor_workshop);
        let mut out: Vec<(u32, Vec<&Recipe>)> = Vec::new();
        for r in self.recipes.iter().filter(|r| stations.contains(&r.workshop)) {
            if let Some(&(item, _)) = r.outputs.first() {
                match out.iter_mut().find(|(i, _)| *i == item) {
                    Some((_, list)) => list.push(r),
                    None => out.push((item, vec![r])),
                }
            }
        }
        out
    }
}

fn parse_input(text: &str) -> Option<Input> {
    let mut parts = text.split(':');
    let kind = parts.next()?;
    let id = parts.next()?.parse().ok()?;
    let count = parts.next()?.parse().ok()?;
    match kind {
        "item" => Some(Input::Item { item: id, count }),
        "cat" => Some(Input::Category { id, count }),
        _ => None,
    }
}

/// The table compiled into the mod.
pub fn table() -> &'static Table {
    static TABLE_DATA: OnceLock<Table> = OnceLock::new();
    TABLE_DATA.get_or_init(|| Table::parse(TABLE))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_generated_table_has_the_kitchen_under_the_farmer() {
        let t = table();
        let farmer = t.npcs.iter().find(|n| n.name == "NPC_Workshop_Farmer_Assistant_01").unwrap();
        assert!(farmer.assistant);
        let kitchen = t.stations.iter().find(|s| s.name == "Craftingstation_Farmer_Kitchen").unwrap();
        assert_eq!(kitchen.unlocked_by, farmer.workshop);
        let stew = t.recipes.iter().find(|r| r.name == "Food_T5_Yakstew").unwrap();
        assert_eq!(stew.workshop, kitchen.workshop);
        assert_eq!(stew.outputs, vec![(2634459448, 5)]);
        let bread = t.recipes.iter().find(|r| r.name == "Food_T3_Flat_Bread").unwrap();
        assert_eq!(bread.charges, 5, "the Oven takes water");
        assert_eq!(stew.inputs.len(), 4);
        assert!(t.products_of(farmer.workshop).iter().any(|(item, _)| *item == 2634459448));
        assert_eq!(t.recipes_for(farmer.workshop, 2634459448).len(), 1);
    }

    #[test]
    fn the_alchemist_makes_potions_at_once() {
        let t = table();
        let alchemist = t.npcs.iter().find(|n| n.name == "NPC_Workshop_Alchemist01").unwrap();
        let potion = t.recipes.iter().find(|r| r.name == "Consumable_Potion_T1_Health").unwrap();
        assert!(potion.instant());
        assert_eq!((potion.workshop, t.crafter(potion.workshop)), (alchemist.workshop, Some(alchemist.workshop)));
        assert!(t.products_of(alchemist.workshop).iter().any(|(item, _)| *item == potion.outputs[0].0));
        assert!(t.crafts(alchemist.workshop));
    }

    #[test]
    fn rows_parse() {
        let t = Table::parse("recipe\t7\t3\t1.5\t10\t0\t4\titem:1:2,cat:9:3\t5:2\tThing\t5\ncategory\t9\t11:1.0,12:2.0\n");
        let r = t.recipe(7).unwrap();
        assert_eq!(r.inputs, vec![Input::Item { item: 1, count: 2 }, Input::Category { id: 9, count: 3 }]);
        assert_eq!((r.seconds, r.energy, r.props, r.makes(5), r.charges), (1.5, 10, 4, 2, 5));
        assert_eq!(t.categories[&9], vec![(11, 1.0), (12, 2.0)]);
    }
}
